     "key": "g2-sprechen",
     "code": "G2",
     "title": "sprechen: e changes to i",
     "chapters": [
      "2.6"
     ],
     "intro": [
      "<em class=\"de\">sprechen</em> (to speak) is a <strong>stem-changing verb</strong>: in the du and er/sie/es forms the <strong>e</strong> of the stem becomes <strong>i</strong>. The endings stay regular."
     ],
     "blocks": [
      {
       "step": "The forms",
       "title": "sprechen in the present tense",
       "table": {
        "head": [
         "Person",
         "Form"
        ],
        "rows": [
         [
          "ich",
          "spreche"
         ],
         [
          "du",
          "sprichst"
         ],
         [
          "er / sie / es",
          "spricht"
         ],
         [
          "wir",
          "sprechen"
         ],
         [
          "ihr",
          "sprecht"
         ],
         [
          "sie / Sie",
          "sprechen"
         ]
        ],
        "say": [
         "ich spreche",
         "du sprichst",
         "er spricht",
         "wir sprechen",
         "ihr sprecht",
         "sie sprechen"
        ],
        "highlight": 1
       }
      },
      {
       "title": "In sentences",
       "examples": [
        [
         "Ich spreche Deutsch.",
         "I speak German."
        ],
        [
         "Sprichst du Englisch?",
         "Do you speak English?"
        ],
        [
         "Sie spricht ein bisschen Spanisch.",
         "She speaks a little Spanish."
        ],
        [
         "Wir sprechen Französisch.",
         "We speak French."
        ]
       ]
      }
     ],
     "rules": [
      [
       "e → i",
       "only for du and er/sie/es"
      ],
      [
       "du sprichst",
       "er/sie/es spricht"
      ],
      [
       "wir sprechen",
       "ihr sprecht, sie sprechen"
      ]
     ],
