     "key": "g5-time",
     "code": "G1",
     "title": "Telling the time",
     "chapters": [
      "5.2",
      "5.5"
     ],
     "intro": [
      "Germans often say <strong>halb</strong> + the <em>next</em> hour: <em class=\"de\">halb zehn</em> is 9:30 (half on the way to ten). Around half past you count from the half: <em class=\"de\">fünf vor halb zehn</em> is 9:25."
     ],
