     "key": "g7-years",
     "code": "G3",
     "title": "Saying years",
     "chapters": [
      "7.8"
     ],
     "intro": [
      "Years before 2000 are read in two halves with <strong>hundert</strong> in between: 1999 = <em class=\"de\">neunzehnhundertneunundneunzig</em>. From 2000 on, say them like normal numbers: 2001 = <em class=\"de\">zweitausendeins</em>.",
      "You say <em class=\"de\">Ich bin 1990 geboren</em> or <em class=\"de\">im Jahr 1990</em> — never “in 1990”."
     ],
